// `run --json` prints one JSON document on stdout: { events: ReviewEvent[], summary: {...} }.
// Exit code 2 means a source failed (events still delivered); 3 means a notification failed.
const out = $input.first().json;
const text = String(out.stdout ?? '').trim();
const lastLine = text.split('\n').filter(Boolean).pop() ?? '{}';
const result = JSON.parse(lastLine);
if (out.exitCode && out.exitCode !== 0 && out.exitCode !== 2) {
  throw new Error(`play-review-notify exited with ${out.exitCode}: ${out.stderr}`);
}
return (result.events ?? []).map((event) => ({ json: { event, summary: result.summary } }));
